import openpyxl, re
path='/root/test-supply.xlsx'
wb=openpyxl.load_workbook(path, data_only=False)

def list_formulas(ws, max_rows=200, max_cols=20):
    out=[]
    for r in range(1, min(ws.max_row, max_rows)+1):
