                out.append((ws.title,r,c,v))
    return out

for name in wb.sheetnames:
    ws=wb[name]
    formulas=list_formulas(ws, max_rows=200, max_cols=30)
    if formulas:
        print('\nSheet',name,'formula count',len(formulas))
        for f in formulas[:30]:
            t,r,c,v=f
            print(f"{t}!{openpyxl.utils.get_column_letter(c)}{r} {v}")
