import urllib.request
from urllib.error import HTTPError
base='https://www.rug.nl/ggdc/docs/'
tries=['pwt1001.xlsx','pwt1001.zip','pwt1001.dta','pwt1001.csv','pwt101.xlsx','pwt101.zip','pwt101.dta','pwt101.csv','pwt1010.xlsx','pwt1010.zip','pwt10_1.xlsx','pwt10-1.xlsx']
for nm in tries:
    url=base+nm
    try:
        req=urllib.request.Request(url, method='HEAD', headers={'User-Agent':'Mozilla/5.0'})
        with urllib.request.urlopen(req, timeout=20) as r:
            print('FOUND',nm,'len',r.headers.get('Content-Length'),'type',r.headers.get('Content-Type'))
    except HTTPError as e:
        print('MISS',nm,'code',e.code)
    except Exception as e:
        print('ERR',nm,str(e)[:60])
